import{_ as a,o as t,c as i,a2 as o}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Update Compatibility, Rollback Limitations, and Recovery","description":"","frontmatter":{"sourceUrl":"https://github.com/sovereignfs/sovereign-os/blob/main/docs/operations/update-recovery-and-compatibility.md"},"headers":[],"relativePath":"sovereign-os/guides/update-recovery-and-compatibility.md","filePath":"sovereign-os/guides/update-recovery-and-compatibility.md"}'),s={name:"sovereign-os/guides/update-recovery-and-compatibility.md"};function n(r,e,l,d,c,h){return t(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="update-compatibility-rollback-limitations-and-recovery" tabindex="-1">Update Compatibility, Rollback Limitations, and Recovery <a class="header-anchor" href="#update-compatibility-rollback-limitations-and-recovery" aria-label="Permalink to &quot;Update Compatibility, Rollback Limitations, and Recovery&quot;">​</a></h1><p><strong>Status:</strong> Draft <strong>Audience:</strong> the person operating a Sovereign OS device — not a Sovereign OS contributor. For engineering-internal detail (schemas, state machines, qualification evidence), see <a href="./../../update/BACKUP_AND_JOURNAL.html">BACKUP_AND_JOURNAL.md</a>, <a href="./../rfcs/0014-appliance-update-system.html">RFC-0014</a>, and the qualification reports under <a href="./../research/"><code>docs/research/</code></a>.</p><h2 id="what-this-covers" tabindex="-1">What this covers <a class="header-anchor" href="#what-this-covers" aria-label="Permalink to &quot;What this covers&quot;">​</a></h2><p>If you run <code>sovereign-update</code> on your device, this page tells you plainly: what it can and can&#39;t do today, what happens to your data during an update, what happens if something goes wrong, and exactly what to run to find out or recover. Nothing here is aspirational — every claim matches what&#39;s actually implemented and, where noted, hardware-tested on a real Raspberry Pi 5.</p><p>This page covers only the <strong>appliance-layer</strong> commands (<code>prepare</code>/<code>backup</code>/<code>stage</code>/<code>activate</code>/<code>restore</code>/<code>prune</code>/<code>rotate-trust</code>/ <code>check</code>). <code>sovereign-update</code> also has a separate, independent set of <strong>base-OS</strong> (root filesystem) commands (<code>stage-base-os</code>/<code>trial-base-os</code>/<code>commit-base-os</code>/<code>discard-base-os</code>) added by <a href="./../rfcs/0016-full-base-os-updates.html">RFC-0016</a> — hardware-verified, but without device-owner guidance here yet. Don&#39;t assume anything on this page applies to them.</p><h2 id="where-things-stand-right-now" tabindex="-1">Where things stand right now <a class="header-anchor" href="#where-things-stand-right-now" aria-label="Permalink to &quot;Where things stand right now&quot;">​</a></h2><p>Be clear-eyed about the current state before relying on this:</p><ul><li>A <strong>production signing key exists</strong> (<code>sovereign-production-1</code>, see <a href="./../adrs/0006-production-signing-key-custody.html">ADR-0006</a>) and its public half now ships baked into the image trust store. <code>v0.1.0-preview.17</code> is the first release signed with it, and it has now been genuinely <em>installed</em> on real Raspberry Pi 5 hardware through <code>prepare</code>/<code>backup</code>/<code>stage</code>/<code>activate</code>, confirmed committed across a reboot. <code>restore</code> has since also been qualified against that install&#39;s real backup, correctly enforcing its version-match safety check and recovering data under <code>--force</code>. <code>prune</code> and <code>rotate-trust</code> still haven&#39;t been exercised as part of a real signed-release install cycle.</li><li>There is <strong>no Console button</strong> yet — installing, backing up, restoring, and pruning are still commands you run yourself over SSH. <code>sovereign-update check</code> <em>does</em> run automatically once a day now (see below) and will tell you if a compatible update exists, but nothing downloads or installs itself; you still trigger <code>prepare</code>/<code>backup</code>/<code>stage</code>/<code>activate</code> by hand.</li><li>Everything here applies to the <strong>preview channel</strong> on <strong>Raspberry Pi 5</strong> only. Nothing about a <code>stable</code> channel or other hardware is implied.</li></ul><h2 id="what-update-paths-are-supported" tabindex="-1">What update paths are supported <a class="header-anchor" href="#what-update-paths-are-supported" aria-label="Permalink to &quot;What update paths are supported&quot;">​</a></h2><p>An update artifact declares the exact range of installed versions it can update <em>from</em> (<code>compatibility.source_versions</code> in its manifest). Your device will refuse an update that:</p><ul><li>targets the wrong device (<code>rpi5-arm64</code> is the only supported identifier today);</li><li>was built for a different channel than the one your device is on;</li><li>is actually a downgrade (an update can only move you forward);</li><li>doesn&#39;t declare your currently-installed version within its supported source range.</li></ul><p>In practice, this means updates are qualified and intended to be applied <strong>one step at a time, from the version you&#39;re actually running</strong> — not &quot;latest always works from anything.&quot; If you&#39;ve been offline for a while and are several versions behind, expect to need an intermediate update rather than a single jump, until a broader compatibility range has been qualified.</p><h2 id="learning-about-updates" tabindex="-1">Learning about updates <a class="header-anchor" href="#learning-about-updates" aria-label="Permalink to &quot;Learning about updates&quot;">​</a></h2><p>You don&#39;t have to already know a new version exists. <code>sovereign-update check</code> runs automatically once a day (with some random jitter, and it catches up on the next boot if the device was off at the scheduled time) and reports what it found:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sovereign-update</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sovereign-update</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # includes the last check result as &quot;update_check&quot;</span></span></code></pre></div><p>It only ever <em>looks</em> — it verifies any candidate release through the same signature/compatibility check <code>prepare</code> uses, and reports <code>up_to_date</code>, <code>update_available</code> (with the version and release-notes URL), or <code>check_failed</code> (network trouble, nothing to worry about — it tries again next scheduled run). It never downloads the update bundle itself, and never starts an update on its own; you still decide when to run <code>prepare</code>/<code>backup</code>/<code>stage</code>/<code>activate</code>. See <a href="./../rfcs/0015-update-discovery.html">RFC-0015</a> and <a href="./../../update/README.html">update/README.md</a>&#39;s &quot;Update Discovery v1&quot; section for the full design.</p><h2 id="what-an-update-actually-does-to-your-device" tabindex="-1">What an update actually does to your device <a class="header-anchor" href="#what-an-update-actually-does-to-your-device" aria-label="Permalink to &quot;What an update actually does to your device&quot;">​</a></h2><p>Running <code>sovereign-update prepare</code> → <code>backup</code> → <code>stage</code> → <code>activate</code> does, in order:</p><ol><li><strong>Verifies</strong> the update&#39;s signature and every artifact digest before touching anything.</li><li><strong>Backs up</strong> your Pi-hole configuration and database, Sovereign configuration, secrets, and the current release pointer — briefly stopping Pi-hole to do it consistently, then restarting it and confirming it&#39;s healthy again before continuing.</li><li><strong>Stages</strong> the new appliance files and Pi-hole container image alongside — not in place of — what&#39;s currently running.</li><li><strong>Activates</strong>: switches over, restarts services, and runs a full local health check (DNS, Console, Pi-hole).</li><li>If everything passes, it <strong>commits</strong>. If anything fails, it <strong>automatically rolls back</strong> to what you had running before, and re-checks health on the rolled-back version too.</li></ol><p>Your Pi-hole admin password, DNS configuration, and query history are never touched by this process except by the backup itself — a normal update commit does not modify them.</p><h2 id="rollback-limitations-—-read-this-before-you-rely-on-it" tabindex="-1">Rollback limitations — read this before you rely on it <a class="header-anchor" href="#rollback-limitations-—-read-this-before-you-rely-on-it" aria-label="Permalink to &quot;Rollback limitations — read this before you rely on it&quot;">​</a></h2><p>Automatic rollback (step 5 above) restores the <strong>previous appliance release and container version</strong>. It does <strong>not</strong> restore your data from the backup, because the current updater rejects any update that would require a data migration in the first place — so there&#39;s nothing for an automatic rollback to undo on the data side. This means:</p><ul><li>Automatic rollback is fast, safe, and already hardware-qualified multiple times (see the <a href="./../research/preview-12-appliance-update-qualification-report.html">preview.12</a> and <a href="./../research/preview-14-appliance-update-qualification-report.html">preview.14</a> qualification reports).</li><li>It is <strong>not</strong> a general-purpose &quot;undo my data changes&quot; button. If you need to recover data specifically (not just the appliance version), use <code>sovereign-update restore &lt;backup-id&gt;</code> — a separate, deliberate command (see <a href="#restoring-from-a-backup">Restoring from a backup</a> below).</li><li>Once data migrations exist in a future update, this section will need to change — right now, migrations are flatly rejected, which is what makes today&#39;s rollback guarantee simple.</li></ul><h2 id="if-an-update-doesn-t-roll-back-on-its-own" tabindex="-1">If an update doesn&#39;t roll back on its own <a class="header-anchor" href="#if-an-update-doesn-t-roll-back-on-its-own" aria-label="Permalink to &quot;If an update doesn&#39;t roll back on its own&quot;">​</a></h2><p>If rollback itself fails its own health check, the updater does <strong>not</strong> guess — it stops and marks the transaction <code>recovery_required</code>, leaving both the old and new state on disk rather than deleting anything. Check what happened:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sovereign-update</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><p>If you see <code>&quot;update_state&quot;: &quot;recovery_required&quot;</code>:</p><ol><li><strong>Don&#39;t delete anything yourself.</strong> The old release and your backup are still there specifically so nothing is lost while you sort this out.</li><li>Check what&#39;s actually running and whether Pi-hole/DNS/Console are reachable — <code>recovery_required</code> on the <em>transaction</em> doesn&#39;t automatically mean the <em>device</em> is down.</li><li>Collect diagnostics before doing anything further:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sovereign-pihole</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sovereign-console</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-pager</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 200</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1/api/v1/health</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/sovereign/current/appliance/bin/verify-update-health</span></span></code></pre></div></li><li>This is a real edge case that needs a human decision, not an automated one — file it as an issue with the output above, or work through <a href="./../../update/BACKUP_AND_JOURNAL.html">BACKUP_AND_JOURNAL.md</a>&#39;s durable journal section to understand exactly which state transition failed.</li></ol><h2 id="restoring-from-a-backup" tabindex="-1">Restoring from a backup <a class="header-anchor" href="#restoring-from-a-backup" aria-label="Permalink to &quot;Restoring from a backup&quot;">​</a></h2><p><code>sovereign-update restore &lt;backup-id&gt;</code> is a separate, deliberate command from automatic rollback — use it when you specifically need to recover Pi-hole state, Sovereign configuration, or secrets from a prior backup (for example, after confirming your current data is bad for a reason unrelated to an in-progress update). It:</p><ul><li>verifies the backup&#39;s integrity before touching any live data;</li><li>extracts into isolated staging first, only then swapping it in;</li><li>keeps your pre-restore data on disk until the restore&#39;s own health check passes;</li><li>automatically rolls back the <em>restore itself</em> if that health check fails, and — same principle as above — stops and preserves both copies rather than guessing if even that fails.</li></ul><p>List available backups with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /data/sovereign/backups/</span></span></code></pre></div><p>Full detail: <a href="./../../update/BACKUP_AND_JOURNAL.html">BACKUP_AND_JOURNAL.md</a>&#39;s Restore Contract section, and the <a href="./../research/restore-hardware-qualification-report.html">restore hardware qualification report</a>.</p><h2 id="if-the-device-itself-won-t-come-back" tabindex="-1">If the device itself won&#39;t come back <a class="header-anchor" href="#if-the-device-itself-won-t-come-back" aria-label="Permalink to &quot;If the device itself won&#39;t come back&quot;">​</a></h2><p>If the appliance won&#39;t boot to a usable state at all — not just a failed update transaction, but the device itself — the documented recovery path today is <strong>reflashing the SD card</strong> with a known-good image. Be aware:</p><ul><li><strong>Reflashing erases the SD card</strong>, including your persistent DATA partition — Pi-hole configuration, gravity database, admin credentials, everything. There is currently no tested &quot;reflash, then restore my data&quot; path; only in-place restore during a live device has been qualified.</li><li>If your data matters and the device is even partially reachable, take a backup (<code>sudo sovereign-update backup &lt;transaction-id&gt;</code>, or a manual copy of <code>/data/sovereign/</code>) before reflashing if you possibly can.</li><li>This is the same reason it&#39;s worth using a spare SD card rather than your daily-driver one whenever you&#39;re testing a new image build.</li></ul><h2 id="cleanup-and-retention" tabindex="-1">Cleanup and retention <a class="header-anchor" href="#cleanup-and-retention" aria-label="Permalink to &quot;Cleanup and retention&quot;">​</a></h2><p>Old backups, inactive release directories, and finished transaction journals don&#39;t accumulate forever. <code>sovereign-update prune [--dry-run]</code> removes what&#39;s safely beyond your configured retention policy — see <a href="./../../update/BACKUP_AND_JOURNAL.html">BACKUP_AND_JOURNAL.md</a>&#39;s Retention status section for exactly what it will and won&#39;t touch (it always keeps your newest backup and your active release, no matter what the policy says). It also now runs on its own once a day; you don&#39;t have to remember to run it.</p><h2 id="signing-key-rotation" tabindex="-1">Signing-key rotation <a class="header-anchor" href="#signing-key-rotation" aria-label="Permalink to &quot;Signing-key rotation&quot;">​</a></h2><p>If you&#39;re the one operating the signing key for your own device(s) (see <a href="./../adrs/0006-production-signing-key-custody.html">ADR-0006</a>), routine key rotation doesn&#39;t require touching each device by hand anymore — <code>sovereign-update rotate-trust</code> applies a signed rotation manifest instead of you copying raw key files over SSH. See <a href="./../../update/README.html">update/README.md</a>&#39;s &quot;Trust Rotation v1&quot; section. This still requires you to run the command yourself; nothing fetches or applies a rotation automatically yet.</p>`,41)])])}const g=a(s,[["render",n]]);export{u as __pageData,g as default};
